# Let me check if the output is a simplified representation of sectors
# Divide the 12x12 input into 4x4 sectors of 3x3 each
# and see which color is most prominent in each

def analyze_sector(mat, row_block, col_block):
    """Extract 3x3 block at (row_block*3, col_block*3)"""
    result = []
    for r in range(row_block*3, row_block*3+3):
        for c in range(col_block*3, col_block*3+3):
            result.append(mat[r][c])
    return result

# Count non-5 colors in each sector
sector_info = {}
for r in range(4):
    for c in range(4):
        sector = analyze_sector(input_demo, r, c)
        counts = {}
        for cell in sector:
            if cell not in counts:
                counts[cell] = 0
            counts[cell] += 1
        # Most common non-5 color
        non_5 = {k: v for k, v in counts.items() if k != 5}
        if non_5:
            most_common = max(non_5, key=non_5.get)
        else:
            most_common = 5  # fallback
        sector_info[(r,c)] = {"counts": counts, "most_common": most_common}
        print(f"Sector ({r},{c}): {counts}, most_common: {most_common}")

